CREATE TABLE TEMPI_FO_T(IDCOMUNE VARCHAR2(6 CHAR) NOT NULL, ID NUMBER(10,0) NOT NULL, TITOLO VARCHAR2(100 CHAR) NOT NULL);

ALTER TABLE TEMPI_FO_T ADD CONSTRAINT PK_TEMPI_FO_T PRIMARY KEY (IDCOMUNE,ID);

 

CREATE TABLE TEMPI_FO_D(IDCOMUNE VARCHAR2(6 CHAR) NOT NULL, ID NUMBER(10,0) NOT NULL, FKID_TEMPI NUMBER(10,0) NOT NULL, TITOLO VARCHAR2(100 CHAR) NOT NULL, DESCRIZIONE VARCHAR2(200 CHAR), TIPO VARCHAR2(1 CHAR) NOT NULL, GIORNI NUMBER(3,0), SCADENZA DATE, ORDINE NUMBER(2,0) NOT NULL);

ALTER TABLE TEMPI_FO_D ADD CONSTRAINT PK_TEMPI_FO_D PRIMARY KEY(IDCOMUNE,ID);

ALTER TABLE TEMPI_FO_D ADD CONSTRAINT FK_TEMPI_FO_T FOREIGN KEY(IDCOMUNE,FKID_TEMPI) REFERENCES TEMPI_FO_T(IDCOMUNE,ID);

 

CREATE TABLE ALBEROPROC_TEMPI(IDCOMUNE VARCHAR2(6 CHAR) NOT NULL, FK_SCID NUMBER(10,0) NOT NULL, FKID_TEMPI NUMBER(10,0) NOT NULL);

ALTER TABLE ALBEROPROC_TEMPI ADD CONSTRAINT PK_ALBEROPROC_TEMPI PRIMARY KEY(IDCOMUNE,FK_SCID,FKID_TEMPI);

ALTER TABLE ALBEROPROC_TEMPI ADD CONSTRAINT FK_ALBPROCTEMPI_ALBERO FOREIGN KEY(IDCOMUNE,FK_SCID) REFERENCES ALBEROPROC(IDCOMUNE,SC_ID);

ALTER TABLE ALBEROPROC_TEMPI ADD CONSTRAINT FK_ALBPROCTEMPI_TEMPI FOREIGN KEY(IDCOMUNE,FKID_TEMPI) REFERENCES TEMPI_FO_T(IDCOMUNE,ID);

ALTER TABLE fo_domande
ADD (
richiedente VARCHAR2(128 char),
intervento VARCHAR2(320 char),
oggetto  VARCHAR2(320 char),
pagamento_avviato NUMBER(1),
pagamento_completato NUMBER(1),
bookmark VARCHAR2(128 char),
upgrade_completo NUMBER(1)
);

